const item = $input.first().json;
const required = ['opportunityName', 'description', 'fitCriteria', 'sourceUrl'];
for (const key of required) {
  if (typeof item[key] !== 'string' || !item[key].trim()) {
    throw new Error(`Missing required field: ${key}`);
  }
}
if (item.opportunityName.length > 200 || item.description.length > 4000 || item.fitCriteria.length > 2000) {
  throw new Error('Input is too long. Keep the name under 200 characters, description under 4,000, and fit criteria under 2,000.');
}
let url;
try { url = new URL(item.sourceUrl.trim()); } catch { throw new Error('Source URL is not valid.'); }
if (url.protocol !== 'https:') throw new Error('Only HTTPS source URLs are allowed.');
if (url.username || url.password) throw new Error('URLs containing credentials are not allowed.');
const host = url.hostname.toLowerCase().replace(/\.$/, '');
if (host === 'localhost' || host.endsWith('.localhost') || host.endsWith('.local') || host.endsWith('.internal') || host.startsWith('[') || /^(?:\d{1,3}\.){3}\d{1,3}$/.test(host)) {
  throw new Error('Local, private-style, and IP-literal hosts are not allowed. Use a public website hostname.');
}
if (url.port && url.port !== '443') throw new Error('Only the standard HTTPS port is allowed.');
item.opportunityName = item.opportunityName.trim();
item.description = item.description.trim();
item.fitCriteria = item.fitCriteria.trim();
item.sourceUrl = url.toString();
return [{ json: item }];

